package com.fasterxml.jackson.databind.ser.impl;

import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.SerializableString;
import com.fasterxml.jackson.core.io.ByteSequence;
import com.fasterxml.jackson.core.io.UTF8ByteSequence;
import com.fasterxml.jackson.core.io.tnt.SerializableString;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.ser.ObjectIdWriter;
import com.fasterxml.jackson.databind.ser.std.StdSerializer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

import com.fasterxml.jackson.core.io.tnt.SerializableString; // Note: In actual Jackson, this is com.fasterxml.jackson.core.io.SerializableString










public class WritableObjectId_writeAsField_TriageGen2Test {

    private JsonGenerator gen;
    private SerializerProvider provider;
    private ObjectIdWriter w;
    private StdSerializer<Object> serializer;

    @Before
    public void setUp() {
        gen = mock(JsonGenerator.class);
        provider = mock(SerializerProvider.class);
        w = mock(ObjectIdWriter.class);
        serializer = mock(StdSerializer.class);
        w.serializer = serializer;
    }

    @Test
    public void testWriteAsField_WhenCanWriteObjectIdIsTrue() throws IOException {
        // Arrange
        WritableObjectId writableObjectId = new WritableObjectId(null);
        // Using reflection or a setter if available to set the private 'id' field
        // Since we can't see the setter, we assume a way to set id or use generateId
        // For the sake of test, we simulate the state via the provided methods if possible
        // Or assume the object is initialized. Let's use reflection to set 'id' for testing.
        setInternalId(writableObjectId, 123L);

        when(gen.canWriteObjectId()).thenReturn(true);

        // Act
        writableObjectId.writeAsField(gen, provider, w);

        // Assert
        verify(gen).writeObjectId("123");
        verify(gen, never()).writeFieldName(any());
        verify(serializer, never()).serialize(any(), any(), any());
        assertTrue(writableObjectId.isIdWritten());
    }

    @Test
    public void testWriteAsField_WhenCanWriteObjectIdIsFalse_AndNameIsNotNull() throws IOException {
        // Arrange
        WritableObjectId writableObjectId = new WritableObjectId(null);
        setInternalId(writableObjectId, "abc");

        when(gen.canWriteObjectId()).thenReturn(false);

        // Mocking SerializableString (it's often an implementation of it)
        com.fasterxml.jackson.core.io.SerializableString name = mock(com.fasterxml.jackson.core.io.SerializableString.class);
        w.propertyName = name;

        // Act
        writableObjectId.writeAsField(gen, provider, w);

        // Assert
        verify(gen).writeFieldName(name);
        verify(serializer).serialize(eq("abc"), eq(gen), eq(provider));
        assertTrue(writableObjectId.isIdWritten());
    }

    @Test
    public void testWriteAsField_WhenCanWriteObjectIdIsFalse_AndNameIsNull() throws IOException {
        // Arrange
        WritableObjectId writableObjectId = new WritableObjectId(null);
        setInternalId(writableObjectId, 999L);

        when(gen.canWriteObjectId()).thenReturn(false);
        w.propertyName = null;

        // Act
        writableObjectId.writeAsField(gen, provider, w);

        // Assert
        verify(gen, never()).writeFieldName(any());
        verify(serializer, never()).serialize(any(), any(), any());
        assertTrue(writableObjectId.isIdWritten());
    }

    /**
     * Helper to set the private 'id' field in WritableObjectId via reflection
     */
    private void setInternalId(WritableObjectId obj, Object id) {
        try {
            java.lang.reflect.Field idField = WritableObjectId.class.getDeclaredField("id");
            idField.setAccessible(true);
            idField.set(obj, id);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
